{"file_path":"src/scanner.js","content":"/**
 * A stream over the code points of the source text, tracking 1-based
 * line/column position per the rules: a line feed moves to the next line
 * and resets the column to 1; a tab moves the column to the next multiple
 * of 4 plus 1; every other code point moves the column forward by 1.
 */
export class CharStream {
  constructor(text) {
    this.chars = Array.from(text)
    this.i = 0
    this.line = 1
    this.col = 1
  }

  atEnd(offset = 0) {
    return this.i + offset >= this.chars.length
  }

  peek(offset = 0) {
    const idx = this.i + offset
    return idx < this.chars.length ? this.chars[idx] : ''
  }

  pos() {
    return { line: this.line, col: this.col }
  }

  advance() {
    const c = this.chars[this.i]
    this.i++
    if (c === '\n') {
      this.line++
      this.col = 1
    } else if (c === '\t') {
      this.col = Math.ceil(this.col / 4) * 4 + 1
    } else {
      this.col++
    }
    return c
  }
}
"}

