{"file_path":"src/numbers.js","content":"import { ScanError } from './errors.js'

const isDigit = c => c >= '0' && c <= '9'
const isHex = c => isDigit(c) || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F')
const isTrailer = c => /[A-Za-z0-9_]/.test(c)

/** Consumes a maximal run of digit | '_' digit, per `test`. */
function consumeDigitRun(s, test) {
  let text = ''
  while (true) {
    if (test(s.peek())) {
      text += s.advance()
    } else if (s.peek() === '_' && test(s.peek(1))) {
      text += s.advance()
      text += s.advance()
    } else {
      break
    }
  }
  return text
}

function finishNumberError(s, pos, text) {
  while (isTrailer(s.peek())) text += s.advance()
  throw new ScanError(pos, `invalid number ${text}`)
}

export function scanNumber(s, pos) {
  let text = s.advance() // first digit

  if (text === '0' && /[xXbBoO]/.test(s.peek())) {
    const p = s.advance()
    text += p
    let test
    if (p === 'x' || p === 'X') test = isHex
    else if (p === 'b' || p === 'B') test = c => c === '0' || c === '1'
    else test = c => c >= '0' && c <= '7'

    if (test(s.peek())) {
      text += consumeDigitRun(s, test)
    } else {
      return finishNumberError(s, pos, text)
    }
  } else {
    text += consumeDigitRun(s, isDigit)

    if (s.peek() === '.' && isDigit(s.peek(1))) {
      text += s.advance()
      text += consumeDigitRun(s, isDigit)
    }

    if (s.peek() === 'e' || s.peek() === 'E') {
      const n1 = s.peek(1)
      if (isDigit(n1)) {
        text += s.advance()
        text += consumeDigitRun(s, isDigit)
      } else if ((n1 === '+' || n1 === '-') && isDigit(s.peek(2))) {
        text += s.advance()
        text += s.advance()
        text += consumeDigitRun(s, isDigit)
      }
    }
  }

  if (isTrailer(s.peek())) return finishNumberError(s, pos, text)
  return { line: pos.line, col: pos.col, kind: 'number', text }
}
"}

