  const e = s.peek()
  if (e === 'n') { s.advance(); return '\n' }
  if (e === 't') { s.advance(); return '\t' }
  if (e === 'r') { s.advance(); return '\r' }
  if (e === '\\') { s.advance(); return '\\' }
  if (e === '"') { s.advance(); return '"' }
  if (e === '0') { s.advance(); return '\0' }
  if (e === 'x') {
    s.advance()
    const h1 = s.peek(), h2 = s.peek(1)
    if (isHex(h1) && isHex(h2)) {
      s.advance()
      s.advance()
      return String.fromCharCode(parseInt(h1 + h2, 16))
    }
    throw new ScanError(bsPos, 'invalid escape \\x')
  }
  if (e === 'u') {
    s.advance()
    if (s.peek() !== '{') throw new ScanError(bsPos, 'invalid escape \\u')
    s.advance()
    let hex = ''
    while (isHex(s.peek())) hex += s.advance()
    if (hex.length === 0 || s.peek() !== '}') throw new ScanError(bsPos, 'invalid escape \\u')
    s.advance()
    const cp = parseInt(hex, 16)
    if (cp > 0x10ffff) throw new ScanError(bsPos, 'invalid escape \\u')
    return String.fromCodePoint(cp)
  }
  throw new ScanError(bsPos, `invalid escape \\${e}`)
}

