  s.advance() // opening quote
  let value = ''
  while (true) {
    if (s.atEnd()) throw new ScanError(pos, 'unterminated string')
    const c = s.peek()
    if (c === '"') {
      s.advance()
      break
    }
    if (c === '\n') throw new ScanError(s.pos(), 'newline in string')
    if (c === '\\') {
      const bsPos = s.pos()
      s.advance()
      if (s.atEnd()) throw new ScanError(pos, 'unterminated string')
      value += scanEscape(s, bsPos)
    } else {
      value += s.advance()
    }
  }
  return { line: pos.line, col: pos.col, kind: 'string', text: JSON.stringify(value) }
