    if (s.atEnd()) throw new ScanError(pos, 'unterminated string')
    const c = s.peek()
    if (c === '"') {
      s.advance()
      break
    }
    value += s.advance()
  }
  return { line: pos.line, col: pos.col, kind: 'rawstring', text: JSON.stringify(value) }
}
