function formatStats(tokens) {
  const counts = Object.fromEntries(STAT_KINDS.map(k => [k, 0]))
  for (const t of tokens) counts[t.kind]++
  const lines = STAT_KINDS.map(k => `${k} ${counts[k]}\n`)
  lines.push(`total ${tokens.length}\n`)
  return lines.join('')
}

async function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || (mode !== 'tokens' && mode !== 'stats')) {
    process.stderr.write('error: usage: cli.js tokens|stats\n')
    process.exitCode = 2
    return
  }

  const text = await readStdin()

  let tokens
  try {
    tokens = tokenize(text)
  } catch (err) {
    if (err instanceof ScanError) {
      process.stderr.write(`error: ${err.pos.line}:${err.pos.col}: ${err.message}\n`)
      process.exitCode = 2
      return
    }
    throw err
  }

  const out = mode === 'tokens' ? formatTokens(tokens) : formatStats(tokens)
  process.stdout.write(out)
  process.exitCode = 0
}

main().catch(err => {
  process.stderr.write(`error: ${err.message}\n`)
  process.exitCode = 2
})
